INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q940722', 'Battle of Ümera', 'Battle of Ümera (Estonian: Ümera lahing), also known as the Battle of Imera (Latvian: Kauja pie Imeras), was a battle during the Livonian Crusade between the Livonian Brothers of the Sword, their Christian Livonian and Latgalian allies, and the Estonians. The Battle was fought near the Jumara, a tributary of the Gauja River in August or September 1210.', 1210, NULL, NULL, NULL, NULL, NULL, 'year', '1210', 47, 'https://en.wikipedia.org/wiki/Battle_of_%C3%9Cmera'),
  ('Q600609', 'Battle of Durbe', 'The Battle of Durbe (Latvian: Durbes kauja, Lithuanian: Durbės mūšis, German: Schlacht an der Durbe) was a medieval battle fought near Durbe, 23 km (14 mi) east of Liepāja, in present-day Latvia during the Livonian Crusade. On 13 July 1260, the Samogitians soundly defeated the joint forces of the Teutonic Knights from Prussia and the Livonian Order from Livonia.', 1260, 7, 13, NULL, NULL, NULL, 'day', '13 July 1260', 62, 'https://en.wikipedia.org/wiki/Battle_of_Durbe'),
  ('Q1640209', 'Battle of Aizkraukle', 'The Battle of Aizkraukle or Ascheraden was fought on 5 March 1279 between the Grand Duchy of Lithuania, led by Traidenis, and the Livonian branch of the Teutonic Order near Aizkraukle (German: Ascheraden) in present-day Latvia. The order suffered a great defeat: 71 knights, including the grand master, Ernst von Rassburg, and Eilart Hoberg, leader of the knights from Danish Estonia, were killed.', 1279, 3, 5, NULL, NULL, NULL, 'day', '5 March 1279', 53, 'https://en.wikipedia.org/wiki/Battle_of_Aizkraukle'),
  ('Q62417', 'Battle of Turaida', 'The Battle of Turaida or Treiden (also known as the Battle on Aa) was fought on June 1, 1298, on the banks of the Gauja River (German: Livländische Aa) near the Turaida Castle (Treiden). The Livonian Order was decisively defeated by the residents of Riga allied with the Grand Duchy of Lithuania under the command of Vytenis.', 1298, 6, 1, NULL, NULL, NULL, 'day', '1 June 1298', 43, 'https://en.wikipedia.org/wiki/Battle_of_Turaida'),
  ('Q497806', 'Battle of Ergeme', 'The Battle of Ērģeme (also Battle of Ermes) (Estonian: Härgmäe lahing; German: Schlacht bei Ermes; Russian: Битва под Эрмесом; Latvian: Ērģemes kauja) was fought on 2 August 1560 in present-day Latvia (near Valka) as part of the Livonian War between the forces of Ivan IV of Russia and the Livonian Confederation. It was the last battle fought by the German knights in Livonia and an important Russian victory.', 1560, 8, 2, NULL, NULL, NULL, 'day', '2 August 1560', 52, 'https://en.wikipedia.org/wiki/Battle_of_%C4%92r%C4%A3eme'),
  ('Q2364604', 'Battles of Wenden', 'The Battles of Wenden were a series of battles for control of the stronghold of Wenden (Cēsis, Kiesia, Võnnu), in present-day Latvia, fought during the Livonian War in 1577 and 1578. Magnus of Livonia besieged the town in August 1577, but was deposed and replaced by Russian forces under Tsar Ivan IV, who eventually sacked the town and castle in what became a symbolic victory.', 1578, 10, 21, NULL, NULL, NULL, 'day', '21 October 1578', 48, 'https://en.wikipedia.org/wiki/Battles_of_Wenden_(1577%E2%80%931578)'),
  ('Q1240241', 'Calendar riots in Riga', 'Calendar Riots in Riga were a series of uprisings by the citizens of Riga between 1584 and 1589 against the authority of the Riga Town Council and King Stephen Báthory, who had issued an order to adopt the Gregorian calendar. Citizens viewed the reform as an imposition of new restrictions, and opposition to the calendar became intertwined with a broader power struggle between the patricians (represented by the town council) and the guilds (representing burghers), as well as a new wave of Catholic persecution.', 1584, NULL, NULL, 1589, NULL, NULL, 'year', '1584–1589', 37, 'https://en.wikipedia.org/wiki/Calendar_riots_in_Riga'),
  ('Q717073', 'Battle of Kokenhausen', 'The Battle of Kokenhausen (Kokenhuza, Latvian: Koknese) was a major battle opening the Polish–Swedish War (1600–1611). It took place on the 13 June (O.S.) or 23 June (N.S.) 1601 near Koknese (in Baltic German Kokenhausen) in Livonia (now in Latvia).', 1601, 6, 23, NULL, NULL, NULL, 'day', '23 June 1601', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kokenhausen'),
  ('Q1413158', 'Battle of Wenden', 'The Battle of Wenden (also known as Battle of Kieś) took place on 7 January 1601, during the Polish–Swedish War (1600–1611). Polish–Lithuanian forces were led by Jürgen von Farensbach (Jerzy Farensbach) and Maciej Dębiński.', 1601, 1, 7, NULL, NULL, NULL, 'day', '7 January 1601', 39, 'https://en.wikipedia.org/wiki/Battle_of_Wenden_(1601)'),
  ('Q7510519', 'Siege of Wolmar', 'The siege of Wolmar occurred during the Polish–Swedish War (1600–1611), between October 18 and December 18, 1601.', 1601, 10, 18, 1601, 12, 18, 'day', '18 October 1601 – 18 December 1601', 39, 'https://en.wikipedia.org/wiki/Siege_of_Wolmar'),
  ('Q937332', 'Battle of Kircholm', 'The Battle of Kircholm took place on 27 September [O.S. 17 September] 1605 during the Polish–Swedish War (1600–1611) near Kircholm, now Salaspils in Latvia. A Swedish expedition besieging Riga was defeated by a smaller Polish–Lithuanian Commonwealth relief force and abandoned the attempt.', 1605, 9, 27, NULL, NULL, NULL, 'day', '27 September 1605', 61, 'https://en.wikipedia.org/wiki/Battle_of_Kircholm'),
  ('Q5037007', 'Capture of Daugavgrīva', 'The Capture of Daugavgriva by Swedish forces in July 1608 occurred during the Polish–Swedish War (1600–1611). Daugavgrīva castle (Polish: Dynemund, Swedish: Dünamünde) was the first objective of the Swedish forces during the campaign of 1608, due to its location near Riga (Daugavgrīva is Riga suburb today), and the fact that it could be used to block that city from the sea.', 1608, 7, 27, NULL, NULL, NULL, 'day', '27 July 1608', 34, 'https://en.wikipedia.org/wiki/Capture_of_Daugavgr%C4%ABva'),
  ('Q748173', 'Battle of Salis', 'The Battle of Salis took place during the Polish–Swedish War (1600–1611) during the night of March 23–24, 1609. After the capture of Pärnu, Jan Karol Chodkiewicz, commander of the Lithuanian army, moved towards Riga, which was besieged by the Swedes under the command of Joachim Frederick von Mansfeld.', 1609, 3, 23, 1609, 3, 24, 'day', '23 March 1609 – 24 March 1609', 34, 'https://en.wikipedia.org/wiki/Battle_of_Salis'),
  ('Q1008542', 'Battle of Daugavgriva', 'The Battle of Daugavgrīva took place on October 6, 1609, during the Polish–Swedish War (1600–1611). The Poles and Lithuanians under Jan Karol Chodkiewicz''s command stood victorious.', 1609, 10, 6, NULL, NULL, NULL, 'day', '6 October 1609', 34, 'https://en.wikipedia.org/wiki/Battle_of_Daugavgr%C4%ABva_(1609)'),
  ('Q10428015', 'Siege of Riga', 'The siege of Riga (Swedish: Belägringen av Riga; Polish: Oblężenie Rygi) was a successful Swedish siege of Riga during the Polish–Swedish War (1621–1625). It led to the capture of the city, and subsequently sent shockwaves through Europe.', 1621, 8, 13, 1621, 9, 15, 'day', '13 August 1621 – 15 September 1621', 37, 'https://en.wikipedia.org/wiki/Siege_of_Riga_(1621)'),
  ('Q609536', 'Battle of Wallhof', 'Battle of Wallhof (Latvian: Valles kauja, also known as Battle of Walmojza) was fought between Sweden and the Polish-Lithuanian Commonwealth on 17 January 1626.', 1626, 1, 7, NULL, NULL, NULL, 'day', '7 January 1626', 41, 'https://en.wikipedia.org/wiki/Battle_of_Wallhof'),
  ('Q595785', 'Siege of Riga', 'The siege of Riga by the Russian army under Tsar Alexei Mikhailovich was the main event of the Russo-Swedish War. The fortifications of Riga consisted of a wall with ditch and 5 bastions around the old town.', 1656, 8, 21, 1656, 10, 5, 'day', '21 August 1656 – 5 October 1656', 48, 'https://en.wikipedia.org/wiki/Siege_of_Riga_(1656)'),
  ('Q4337377', 'Siege of Dyneburg', 'The siege of Dyneburg by the Russian Army under Tsar Alexei Mikhailovich was one of the first events of the Russo-Swedish War (1656–1658), a theater of the Second Northern War. The siege began on 18 July 1656.', 1656, 7, 18, 1656, 7, 31, 'day', '18 July 1656 – 31 July 1656', 34, 'https://en.wikipedia.org/wiki/Siege_of_Dyneburg'),
  ('Q4337389', 'Storm of Kokenhusen', 'The Storm of Kokenhusen by the Russian Army under Tsar Alexei Mikhailovich was one of the first events of the Russo-Swedish War (1656–1658), a theater of the Second Northern War. On 14 August 1656 Russian troops stormed and captured the well-fortified town of Kokenhusen (Koknese) in Swedish Livonia (present-day Latvia) According to the Tsar, this town “was very strong, had a deep moat, like a small brother of the Kremlin''s moat, and its fortress is like a son of Smolensk''s fortress”.', 1656, 8, 14, NULL, NULL, NULL, 'day', '14 August 1656', 34, 'https://en.wikipedia.org/wiki/Storm_of_Kokenhusen'),
  ('Q815200', 'Siege of Riga', 'The sieges of Riga were two sieges which took place on February 22 and June 15, 1700, in Riga during the Great Northern War. The Swedish garrison of about 4,000 men under the command of Erik Dahlberg successfully repulsed the Saxons until the main Swedish army under Charles XII of Sweden arrived to sweep the Saxons away in the Battle of Riga which ended the period of sieges for the year.', 1700, 2, 22, NULL, NULL, NULL, 'day', '22 February 1700', 45, 'https://en.wikipedia.org/wiki/Siege_of_Riga_(1700)'),
  ('Q826133', 'Crossing of the Düna', 'The Crossing of the Düna (also known as Battle of Daugava or Battle of Spilves) took place during the Great Northern War on 19 July 1701 near the city of Riga, present-day Latvia. The Swedish king Charles XII was in hot pursuit of king Augustus II the Strong of the Polish–Lithuanian Commonwealth and Saxony.', 1701, 7, 18, NULL, NULL, NULL, 'day', '18 July 1701', 52, 'https://en.wikipedia.org/wiki/Crossing_of_the_D%C3%BCna'),
  ('Q169602', 'Battle of Jakobstadt', 'The Battle of Jakobstadt (Lithuanian: Jėkabpilio mūšis, Latvian: Kauja pie Jēkabpils, Swedish: Slaget vid Jakobstadt, Polish: Krzyżbork) was fought in the Great Northern War. It took place on 25 July 1704 (O.S.) / 26 July 1704 (Swedish calendar) / 5 August 1704 (N.S.) between a Swedish army under Adam Ludwig Lewenhaupt and a combined Polish/Russian force under Great Hetman Michał Serwacy Wiśniowiecki at the town of Jēkabpils (German: Jakobstadt) in the Duchy of Courland and Semigallia.', 1704, 8, 5, NULL, NULL, NULL, 'day', '5 August 1704', 48, 'https://en.wikipedia.org/wiki/Battle_of_Jakobstadt'),
  ('Q704567', 'Battle of Gemauerthof', 'The Battle of Gemauerthof took place during the Great Northern War, fought south of Riga near Jelgava, in present-day Latvia in July 1705. The Swedish forces under Adam Ludwig Lewenhaupt fought a Russian army under Boris Sheremetev.', 1705, 7, 26, NULL, NULL, NULL, 'day', '26 July 1705', 55, 'https://en.wikipedia.org/wiki/Battle_of_Gemauerthof'),
  ('Q447901', 'Siege of Riga', 'The siege of Riga in 1709–1710 was a military operation of the army of the Tsardom of Russia during the Great Northern War against the forces of the Swedish Empire defending the fortress of Riga. As a result of the operation, Riga was taken by Russian troops.', 1709, 11, 14, 1710, 7, 4, 'day', '14 November 1709 – 4 July 1710', 39, 'https://en.wikipedia.org/wiki/Siege_of_Riga_(1709%E2%80%931710)'),
  ('Q4087482', 'Battle of Ekau', 'The Battle of Ekau (also the Battle of Iecava) took place during the initial phase of the French invasion of Russia. Napoleon''s troops from the X Corps of Marshal MacDonald, who had the advantage, defeated the troops of Alexander I defending under the command of General Friedrich von Löwis of Menar.', 1812, 7, 19, NULL, NULL, NULL, 'day', '19 July 1812', 37, 'https://en.wikipedia.org/wiki/Battle_of_Ekau'),
  ('Q4438394', 'Battle of Mesoten', 'The Battle of Mesothen (Mesoten) took place from 26–30 September to 1 October 1812, between the Russian Corps of Finland and the French-allied Prussian Auxiliary Corps. It was fought near the Latvian town of Mežotne (German: Mesothen/Mesoten), then part of the Courland Governorate.', 1812, 9, 29, NULL, NULL, NULL, 'day', '29 September 1812', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mesoten'),
  ('Q7510345', 'Siege of Riga', 'The siege of Riga was a military operation during the Napoleonic Wars. The siege lasted five months from July – December 1812, during which the left flank of Napoleon''s "Great Army" (La Grande Armée) tried to gain a favorable position for an attack on Russian-controlled port city Riga, the capital of the Governorate of Livonia.', 1812, 7, NULL, NULL, NULL, NULL, 'month', 'July 1812', 34, 'https://en.wikipedia.org/wiki/Siege_of_Riga_(1812)'),
  ('Q16354042', 'Tukums Uprising', 'The Tukums Uprising (in Latvian: Tukuma sacelšanās), also called the Tukums War, was an armed uprising against the Russian rule in the city of Tukums, today Latvia. During the uprising, the rebels created a temporary republic: the Republic of Tukums.', 1905, 12, 13, 1905, 12, 16, 'day', '13 December 1905 – 16 December 1905', 26, 'https://en.wikipedia.org/wiki/Tukums_Uprising'),
  ('Q4296566', 'Christmas Battles', 'The Christmas Battles (Latvian: Ziemassvētku kaujas; German: Aa-Schlachten; Russian: Митавская операция) were offensive operations conducted by the Imperial Russian Army and Latvian Riflemen during World War I in the area of Jelgava, Latvia, by the Russian 12th Army of the Northern Front. The operation took place from 23 December until 29 December 1916 according to the Julian Calendar (or 5 January to 11 January according to the Gregorian Calendar).', 1917, NULL, NULL, 1917, 1, 11, 'year', '1917', 48, 'https://en.wikipedia.org/wiki/Christmas_Battles'),
  ('Q11347885', 'Battle of Riga', 'The Riga offensive (Russian: Рижская операция), also called the Jugla offensive or the Battle of Riga (German: Schlacht um Riga), took place in early September 1917 and was the last major campaign on the Eastern Front of World War I before the Russian Provisional Government and its army began disintegrating. The battle was fought between Oskar von Hutier''s German Eighth Army and Dmitri Parsky''s Russian Twelfth Army.', 1917, 9, 1, 1917, 9, 3, 'day', '1 September 1917 – 3 September 1917', 55, 'https://en.wikipedia.org/wiki/Riga_offensive_(1917)'),
  ('Q543042', 'Latvian War of Independence', 'The Latvian War of Independence (Latvian: Latvijas Neatkarības karš), sometimes called Latvia''s freedom battles (Latvijas brīvības cīņas) or the Latvian War of Liberation (Latvijas atbrīvošanas karš), was a series of military conflicts in Latvia between 5 December 1918, after the newly proclaimed Republic of Latvia was invaded by Soviet Russia, and the signing of the Latvian-Soviet Riga Peace Treaty on 11 August 1920. The war can be divided into several stages: Soviet offensive of 1918–1919, German-Latvian liberation of Kurzeme and Riga, Estonian-Latvian liberation of Vidzeme, Bermontian…', 1918, 12, 5, 1920, 8, 11, 'day', '5 December 1918 – 11 August 1920', 67, 'https://en.wikipedia.org/wiki/Latvian_War_of_Independence'),
  ('Q3089540', 'Soviet westward offensive of 1918–1919', 'The Soviet westward offensive of 1918–1919 was part of the campaign by Soviet Russia into areas abandoned by the Ober Ost garrisons that were being withdrawn to Germany following that country''s defeat in World War I. The initially successful offensive against the Republic of Estonia ignited the Estonian War of Independence which ended with the Soviet recognition of Estonia. Similarly, the campaigns against the Republic of Latvia and Republic of Lithuania ultimately failed, resulting in the Latvian–Soviet Peace Treaty and Soviet–Lithuanian Peace Treaty respectively.', 1918, 11, 18, 1919, 3, NULL, 'day', '18 November 1918 – March 1919', 52, 'https://en.wikipedia.org/wiki/Soviet_westward_offensive_of_1918%E2%80%931919'),
  ('Q183286', 'Battle of Cēsis', 'The Battle of Cēsis (Latvian: Cēsu kaujas; Estonian: Võnnu lahing, Battle of Võnnu; German: Schlacht von Wenden, Battle of Wenden), fought near Cēsis (Wenden) in June 1919, was a decisive battle in the Estonian War of Independence and the Latvian War of Independence. After heavy fighting, an Estonian force moving from the north, supplemented by Latvian units, repelled Baltic German attacks and went on a full counter-attack.', 1919, 6, 5, 1919, 6, 23, 'day', '5 June 1919 – 23 June 1919', 56, 'https://en.wikipedia.org/wiki/Battle_of_C%C4%93sis_(1919)'),
  ('Q1135598', 'Battle of Daugavpils', 'The Battle of Daugavpils, or Battle of Dyneburg, or Operation Winter was the final battle during the Polish–Soviet War of 1919. A joint Polish and Latvian force, operating under Polish Staff orders known as "Operation Winter", attacked the Red Army garrison in Dunaburg, or Daugavpils, from 3 to 5 January 1920.', 1920, 1, 5, 1920, 1, 25, 'day', '5 January 1920 – 25 January 1920', 41, 'https://en.wikipedia.org/wiki/Battle_of_Daugavpils'),
  ('Q1377536', 'Latvian–Soviet Peace Treaty (1920)', 'The Latvian–Soviet Peace Treaty, also known as the Treaty of Riga, was signed on 11 August 1920 by representatives of the Republic of Latvia and Soviet Russia. It officially ended the Latvian War of Independence.', 1920, 8, 11, NULL, NULL, NULL, 'day', '11 August 1920', 62, 'https://en.wikipedia.org/wiki/Latvian%E2%80%93Soviet_Peace_Treaty'),
  ('Q6497433', 'Latvian church property referendum, 1923', 'A referendum on the transfer of church property was held in Latvia on 1 and 2 September 1923, the first time a referendum had been held in the country. Voters were asked whether the government should be stopped from transferring the Lutheran St James''s Church in Riga to the Roman Catholic Church.', 1923, 9, 2, NULL, NULL, NULL, 'day', '2 September 1923', 37, 'https://en.wikipedia.org/wiki/1923_Latvian_church_property_referendum'),
  ('Q6497437', 'Latvian citizenship referendum, 1927', 'A referendum on the citizenship law was held in Latvia on 17 and 18 December 1927. Voters were asked whether they approved of repealing the amendments made to the citizenship law by the Saeima.', 1927, 12, 18, NULL, NULL, NULL, 'day', '18 December 1927', 34, 'https://en.wikipedia.org/wiki/1927_Latvian_citizenship_referendum'),
  ('Q11227670', 'Latvian Riga Cathedral referendum, 1931', 'A referendum on the transfer of Riga Cathedral to the Lutheran Church was held in Latvia on 5 and 6 September 1931. Although 80% of those voting voted in favour, they represented only 32% of registered voters, and the referendum required 50% of registered voters to vote in favour for the proposal to pass.', 1931, 9, 6, NULL, NULL, NULL, 'day', '6 September 1931', 34, 'https://en.wikipedia.org/wiki/1931_Latvian_Riga_Cathedral_referendum'),
  ('Q3182543', '1934 Latvian coup d''état', 'The 1934 Latvian coup d''état (Latvian: 1934. gada 15.', 1934, 5, 15, NULL, NULL, NULL, 'day', '15 May 1934', 59, 'https://en.wikipedia.org/wiki/1934_Latvian_coup_d''%C3%A9tat'),
  ('Q6497365', 'Latvian Insurance Law referendum, 1934', 'A referendum on the Insurance Law was held in Latvia on 24 and 25 February 1934. The referendum was initiated by the Latvian Social Democratic Workers'' Party and its supporters and asked voters whether they approved of the law "On Provision in cases of old age, disability and unemployment", more commonly known as the Insurance Law.', 1934, 2, 25, NULL, NULL, NULL, 'day', '25 February 1934', 34, 'https://en.wikipedia.org/wiki/1934_Latvian_Insurance_Law_referendum'),
  ('Q58473', 'occupation of the Baltic states', 'The Baltic states—Estonia, Latvia, and Lithuania—were occupied and annexed by the Soviet Union in 1940 and remained under its control until its dissolution in 1991. For a period of several years during World War II, Nazi Germany occupied the Baltic states after it invaded the Soviet Union in 1941.', 1940, NULL, NULL, 1991, NULL, NULL, 'year', '1940–1991', 69, 'https://en.wikipedia.org/wiki/Occupation_of_the_Baltic_states'),
  ('Q718738', 'Soviet occupation of Latvia in 1940', 'The Soviet occupation of Latvia in 1940 refers to the military occupation of the Republic of Latvia by the Soviet Union under the provisions of the 1939 Molotov–Ribbentrop Pact with Nazi Germany and its Secret Additional Protocol signed in August 1939. In 1989, the USSR condemned the 1939 secret protocol between Nazi Germany and itself that had led to the invasion and occupation of the three Baltic countries, including Latvia.', 1940, NULL, NULL, NULL, NULL, NULL, 'year', '1940', 58, 'https://en.wikipedia.org/wiki/Soviet_occupation_of_Latvia_in_1940'),
  ('Q1324428', 'Baltic Operation', 'The Baltic strategic defensive operation (Russian: Прибалтийская стратегическая оборонительная операция, romanized: Pribaltiyskaya strategicheskaya oboronitel''naya operatsiya) encompassed the operations of the Red Army from 22 June to 9 July 1941 conducted over the territories of Soviet-occupied Lithuania, Latvia, and Estonia in response to the offensive launched by the Wehrmacht in Operation Barbarossa.', 1941, 7, 9, NULL, NULL, NULL, 'day', '9 July 1941', 56, 'https://en.wikipedia.org/wiki/Baltic_operation'),
  ('Q2915791', 'Liepāja Massacres', 'The Liepāja massacres were a series of mass executions, many public or semi-public, in and near the city of Liepāja (German: Libau), on the west coast of Latvia in 1941 after the German occupation of Latvia. The main perpetrators were detachments of the Einsatzgruppen, the Sicherheitsdienst (SD), the Ordnungspolizei (ORPO), and Latvian auxiliary police and militia forces.', 1941, 6, 29, 1942, 4, NULL, 'day', '29 June 1941 – April 1942', 48, 'https://en.wikipedia.org/wiki/Liep%C4%81ja_massacres'),
  ('Q3495737', 'Jelgava massacres', 'The Jelgava massacres were the killing of the Jewish population of the city of Jelgava, Latvia that occurred in the second half of July or in early August 1941. The murders were carried out by German police units under the command of Alfred Becu, with a significant contribution by Latvian auxiliary police organized by Mārtiņš Vagulāns.', 1941, 8, NULL, NULL, NULL, NULL, 'month', 'August 1941', 37, 'https://en.wikipedia.org/wiki/Jelgava_massacres'),
  ('Q7075770', 'German occupation of the Baltic states during World War II', 'After the German invasion of the Soviet Union, the Baltic states were under military occupation by Nazi Germany from 1941 to 1944. Initially, many Estonians, Latvians, and Lithuanians considered the Germans liberators from the Soviet Union.', 1941, 7, NULL, 1944, NULL, NULL, 'month', 'July 1941 – 1944', 37, 'https://en.wikipedia.org/wiki/German_occupation_of_the_Baltic_states_during_World_War_II'),
  ('Q697172', 'Courland Pocket', 'The Courland Pocket was a pocket located on the Courland Peninsula in Latvia on the Eastern Front of World War II from 9 October 1944 to 22 May 1945. The last battle with a regular German army unit took place here on May 22, 1945.', 1944, 10, 9, 1945, 5, 10, 'day', '9 October 1944 – 10 May 1945', 61, 'https://en.wikipedia.org/wiki/Courland_Pocket'),
  ('Q2662170', 'Riga Offensive', 'The Riga offensive (Russian: Рижская наступательная операция, lit. ''Riga offensive operation'') was part of the larger Baltic offensive on the Eastern Front during World War II. It took place late in 1944, and drove German forces from the city of Riga.', 1944, 10, 24, 1944, 10, 24, 'day', '24 October 1944', 50, 'https://en.wikipedia.org/wiki/Riga_offensive_(1944)'),
  ('Q595321', 'Singing Revolution', 'The Singing Revolution was a series of events from 1987 to 1991 that led to the restoration of independence of the three Soviet-occupied Baltic countries of Estonia, Latvia, and Lithuania at the end of the Cold War. The Soviet Union annexed the Baltics around 1940, following the Molotov-Ribbentrop Pact (a non-aggression agreement with Nazi Germany), though this annexation was not widely recognized.', 1987, NULL, NULL, 1991, NULL, NULL, 'year', '1987–1991', 73, 'https://en.wikipedia.org/wiki/Singing_Revolution'),
  ('Q4992563', 'The Barricades', 'The Barricades (Latvian: Barikādes), also the Time of the Barricades (Barikāžu laiks) or the Barricades of 1991 (1991. gada barikādes) were a series of confrontations between the Republic of Latvia and the Union of Soviet Socialist Republics in January 1991 which took place mainly in Riga.', 1991, 1, NULL, 1991, 1, 27, 'month', 'January 1991 – 27 January 1991', 58, 'https://en.wikipedia.org/wiki/The_Barricades'),
  ('Q4393786', 'Latvian citizenship referendum, 1998', 'A referendum on the citizenship law was held in Latvia on 3 October 1998. The Saeima had made amendments to the law in June that increased the opportunities for naturalisation and provided the additional option of obtaining Latvian citizenship for non-citizens (nepilsoņi) and stateless persons (bezvalstnieki) born in Latvia from August 1991 onwards.', 1998, 10, 3, NULL, NULL, NULL, 'day', '3 October 1998', 39, 'https://en.wikipedia.org/wiki/1998_Latvian_citizenship_referendum'),
  ('Q4393784', 'Latvian pensions referendum, 1999', 'A referendum on state pensions was held in Latvia on 13 November 1999. A bill amending the state pension law had been passed by the Saeima on 5 August.', 1999, 11, 13, NULL, NULL, NULL, 'day', '13 November 1999', 37, 'https://en.wikipedia.org/wiki/1999_Latvian_pensions_referendum'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q4140767', 'Latvian security laws referendum', 'A referendum on two proposed security laws was held in Latvia on 7 July 2007; the referendum had been called after the president refused to sign the laws, claiming possible influence of oligarchs on Latvia''s national security, and after 212,000 signatures had been collected, meeting the requirement of about 150,000 signatures. Although the referendum failed to reach the quorum of 453,730 votes, the results showed massive disapproval of the amendments.', 2007, 7, 7, NULL, NULL, NULL, 'day', '7 July 2007', 37, 'https://en.wikipedia.org/wiki/2007_Latvian_security_laws_referendum'),
  ('Q607950', 'Latvian constitutional referendum, 2008', 'A constitutional referendum to amend the constitution of Latvia in order to allow one-tenth of the total registered electorate to initiate a popular referendum to dissolve the Latvian parliament was held in Latvia on 2 August 2008. The referendum on this issue was triggered when the Government of Latvia voted against an opposition motion to adopt this change to the constitution, which resulted in a referendum in Latvia by law.', 2008, 8, 2, NULL, NULL, NULL, 'day', '2 August 2008', 43, 'https://en.wikipedia.org/wiki/2008_Latvian_constitutional_referendum'),
  ('Q4393787', 'Latvian pensions law referendum, 2008', 'A referendum on amendments in the pensions law was held in Latvia on 23 August 2008. It failed due to low turnout, as 453,730 votes (half of the votes cast in the previous parliamentary election) would have been necessary to make it valid.', 2008, 8, 23, NULL, NULL, NULL, 'day', '23 August 2008', 37, 'https://en.wikipedia.org/wiki/2008_Latvian_pensions_law_referendum'),
  ('Q2981156', 'Latvian parliamentary dissolution referendum', 'A referendum on whether the Saeima should be dissolved early was held in Latvia on 23 July 2011. President Valdis Zatlers used his parliamentary dissolution power for the first time in the history of Latvia.', 2011, 7, 23, NULL, NULL, NULL, 'day', '23 July 2011', 45, 'https://en.wikipedia.org/wiki/2011_Latvian_parliamentary_dissolution_referendum'),
  ('Q15220536', 'Riga supermarket roof collapse', 'On 21 November 2013 the roof of a Maxima shopping centre in the Zolitūde neighbourhood of Riga, Latvia, collapsed at 17:44 local time, resulting in the deaths of 54 people, including three rescue workers, and injuries to another 41 people. An unknown number of people were able to leave the store on their own after the initial collapse.', 2013, 11, 21, NULL, NULL, NULL, 'day', '21 November 2013', 62, 'https://en.wikipedia.org/wiki/Zolit%C5%ABde_shopping_centre_roof_collapse'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
